-- Adds new website-owned tables only. Does not modify the six legacy tables.
CREATE TABLE IF NOT EXISTS web_state (id TINYINT PRIMARY KEY, revision BIGINT NOT NULL, document JSON NOT NULL, updated_at DATETIME(3) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS web_room (room_id VARCHAR(50) PRIMARY KEY, room_name VARCHAR(255) NOT NULL, capacity INT NOT NULL, status VARCHAR(30) NOT NULL, location VARCHAR(255), is_deleted TINYINT NOT NULL DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS web_user (user_id VARCHAR(50) PRIMARY KEY, full_name VARCHAR(255), email VARCHAR(255), role_name VARCHAR(30), status VARCHAR(30), is_deleted TINYINT NOT NULL DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS web_equipment (equipment_id VARCHAR(50) PRIMARY KEY, room_id VARCHAR(50), equipment_name VARCHAR(255) NOT NULL, total_quantity INT NOT NULL, status VARCHAR(30) NOT NULL, unavailable_quantity INT NOT NULL DEFAULT 0, is_deleted TINYINT NOT NULL DEFAULT 0, INDEX web_equipment_room(room_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS web_meeting (meeting_id VARCHAR(50) PRIMARY KEY, room_id VARCHAR(50), organizer_id VARCHAR(50), title VARCHAR(255) NOT NULL, description TEXT, start_time DATETIME NOT NULL, end_time DATETIME NOT NULL, status VARCHAR(30) NOT NULL, participants JSON NOT NULL, is_deleted TINYINT NOT NULL DEFAULT 0, INDEX web_meeting_room_time(room_id,start_time,end_time)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS web_equipment_booking (booking_id VARCHAR(160) PRIMARY KEY, meeting_id VARCHAR(50), equipment_id VARCHAR(50) NOT NULL, quantity INT NOT NULL, start_time DATETIME NOT NULL, end_time DATETIME NOT NULL, status VARCHAR(30) NOT NULL, is_deleted TINYINT NOT NULL DEFAULT 0, INDEX web_equipment_booking_time(equipment_id,start_time,end_time)) ENGINE=InnoDB;
